import { appendFileSync, mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
const root = process.cwd();
const output = process.argv[2] === "generate" ? ".generated/shared/value.txt" : ".results/test.txt";
mkdirSync(dirname(join(root, output)), { recursive: true });
if (process.argv[2] === "generate") writeFileSync(output, "ready\n");
else {
  const child = Bun.spawn(["cargo", "run", "--locked", "--offline", "--quiet", "--manifest-path", "🧩️subject/📦️packages/🦀️rust/Cargo.toml", "--bin", "consumer"], { cwd: root, env: { ...process.env, CARGO_TARGET_DIR: join(root, ".compiler") }, stdout: "pipe", stderr: "pipe" });
  const [stdout, stderr, code] = await Promise.all([new Response(child.stdout).text(), new Response(child.stderr).text(), child.exited]);
  if (code !== 0) throw new Error(stderr);
  writeFileSync(output, stdout);
}
appendFileSync(".invocations", process.argv[2] + "\n");
